scripts.primality_indep.py:
"""Independent primality tools. NO sympy import anywhere in this module.

1. flint_is_prime: python-flint 0.9.0 (FLINT 3.6.0) fmpz.is_prime -> fmpz_is_prime, a PROVING test
   (retrieved FLINT docs: Pocklington/Morrison/BLS then APR-CL; returns 1 only if proven prime).
2. own_bpsw: this reviewer's own Baillie-PSW (strong base-2 Miller-Rabin + strong Lucas, Selfridge
   method A), written for this review. Probable-prime verdict only.
3. openssl_prime: `openssl prime` (OpenSSL 3.0.13), probabilistic Miller-Rabin. Probable-prime only.
4. fermat2_composite_witness: pow(2, n-1, n) != 1 is a PROOF of compositeness.
"""
import subprocess
from math import isqrt

def flint_is_prime(n):
    import flint
    return bool(flint.fmpz(n).is_prime())

def _strong_mr(n, a):
    d, s = n - 1, 0
    while d % 2 == 0:
        d //= 2; s += 1
    x = pow(a, d, n)
    if x == 1 or x == n - 1:
        return True
    for _ in range(s - 1):
        x = x * x % n
        if x == n - 1:
            return True
    return False

def _jacobi(a, n):
    assert n > 0 and n % 2 == 1
    a %= n
    res = 1
    while a:
        while a % 2 == 0:
            a //= 2
            if n % 8 in (3, 5):
                res = -res
        a, n = n, a
        if a % 4 == 3 and n % 4 == 3:
            res = -res
        a %= n
    return res if n == 1 else 0

def _strong_lucas(n):
    # Selfridge method A: D in 5, -7, 9, -11, ... with jacobi(D, n) == -1
    if isqrt(n) ** 2 == n:
        return False
    D = 5
    while True:
        j = _jacobi(D, n)
        if j == -1:
            break
        if j == 0 and abs(D) != n:
            return False
        D = -D - 2 if D > 0 else -D + 2
    P, Q = 1, (1 - D) // 4
    d, s = n + 1, 0
    while d % 2 == 0:
        d //= 2; s += 1
    # compute U_d, V_d mod n by binary method
    U, V, Qk = 0, 2, 1  # U_0, V_0, Q^0
    inv2 = pow(2, -1, n)
    for bit in bin(d)[2:]:
        # double: U_2k = U_k V_k ; V_2k = V_k^2 - 2 Q^k
        U, V = (U * V) % n, (V * V - 2 * Qk) % n
        Qk = (Qk * Qk) % n
        if bit == '1':
            # add one: U_{k+1} = (P U_k + V_k)/2 ; V_{k+1} = (D U_k + P V_k)/2
            U, V = ((P * U + V) * inv2) % n, ((D * U + P * V) * inv2) % n
            Qk = (Qk * Q) % n
    if U == 0 or V == 0:
        return True
    for _ in range(s - 1):
        V = (V * V - 2 * Qk) % n
        Qk = (Qk * Qk) % n
        if V == 0:
            return True
    return False

SMALL = [p for p in range(2, 1000) if all(p % q for q in range(2, isqrt(p) + 1))]

def own_bpsw(n):
    if n < 2:
        return False
    for p in SMALL:
        if n == p:
            return True
        if n % p == 0:
            return False
    return _strong_mr(n, 2) and _strong_lucas(n)

def openssl_prime(n):
    out = subprocess.run(['openssl', 'prime', str(n)], capture_output=True, text=True).stdout.strip()
    if out.endswith('is not prime'):
        return False, out
    if out.endswith('is prime'):
        return True, out
    raise RuntimeError(out)

def fermat2_composite_witness(n):
    return pow(2, n - 1, n) != 1

# sanity self-test on known values (Carmichael / strong pseudoprimes / Mersenne)
def selftest():
    known_prime = [2**127 - 1, 2**89 - 1, 1000000007]
    known_comp = [561, 3215031751, 2152302898747, 3474749660383, 341550071728321,
                  3825123056546413051, 318665857834031151167461, (2**64 + 13) * (2**64 + 51)]
    r = {'own_bpsw_primes_ok': all(own_bpsw(p) for p in known_prime),
         'own_bpsw_composites_rejected': all(not own_bpsw(c) for c in known_comp),
         'flint_primes_ok': all(flint_is_prime(p) for p in known_prime),
         'flint_composites_rejected': all(not flint_is_prime(c) for c in known_comp)}
    # Lucas pseudoprime check: 5459 is a strong Lucas pseudoprime (should pass lucas alone) but MR2 rejects
    r['strong_lucas_psp_5459_passes_lucas_alone'] = _strong_lucas(5459)
    r['own_bpsw_rejects_5459'] = not own_bpsw(5459)
    # cross-check own_bpsw vs flint on all odd n in a range
    mism = [n for n in range(3, 200000, 2) if own_bpsw(n) != flint_is_prime(n)]
    r['own_bpsw_vs_flint_mismatches_below_2e5'] = mism[:10]
    return r

